def numDifferentWords(s: str) -> int:
    # prev2 = dp[i-2], prev1 = dp[i-1]，dp[i] 表示前 i 位的拆法数
    if not s:
        return 0
    prev2, prev1 = 1, 1 if s[0] != '0' else 0
    for i in range(2, len(s) + 1):
        cur = 0
        if s[i - 1] != '0':
            cur += prev1                 # 最后一位单独成字母 1..9
        if s[i - 2] != '0' and int(s[i - 2:i]) <= 26:
            cur += prev2                 # 最后两位组成 10..26
        prev2, prev1 = prev1, cur
    return prev1
